<script setup lang="ts">
const api=useApi(); const { data: leads, refresh }=await useAsyncData('admin-leads',()=>api.request<any[]>('/admin/leads').catch(()=>[]))
async function setStatus(id:string,status:string){await api.request(`/admin/leads/${id}/status`,{method:'POST',body:{status}});await refresh()}
</script>
<template><div><div class="mb-5"><p class="label-mono text-signal-deep">Demand</p><h1 class="mt-1 font-display text-[32px] tracking-[-.04em]">Leads.</h1><p class="mt-1 text-[11.5px] text-ink/45">Website enquiries and configurator requests.</p></div><div class="space-y-2"><div v-for="l in leads" :key="l._id" class="a-card flex flex-col gap-3 p-4 md:flex-row md:items-center"><div class="flex-1"><div class="flex items-center gap-2"><p class="text-[12px] font-medium">{{ l.name }}</p><span class="font-mono text-[8px] uppercase text-ink/30">{{ l.type }}</span></div><p class="mt-1 text-[11px] text-ink/50">{{ l.message }}</p><p class="mt-1 font-mono text-[8px] text-ink/30">{{ l.email }} · {{ l.company || 'individual' }} · {{ shortDate(l.createdAt) }}</p></div><div class="flex items-center gap-2"><select :value="l.status" class="rounded border border-ink/12 bg-bone px-2 py-1.5 font-mono text-[8px] uppercase" @change="setStatus(l._id, ($event.target as HTMLSelectElement).value)"><option>new</option><option>qualified</option><option>won</option><option>closed</option></select></div></div></div></div></template>
